// Set the location hash without retriggering the router (the hashchange handler honors this flag).
function routerSetHash(h) {
  if (location.hash === h) return;
  window.__suppressHash = true;
  location.hash = h;
}

// Router terminal registry (CREATE2-unified across testnets) — installed as a terminal on every revnet
// by REVDeployer. It exposes the standard pay/previewPayFor and swaps the payer's input token into the
// project's accounting token, so a payer can pay USDC into an ETH/USD-accounting revnet. Resolve the
// router from the manifest per-chain (JBRouterTerminalRegistry — deployed on all chains; it routes the
// swap-pay to the project's resolved terminal). The old hardcoded 0x986cda… was stale (not in the manifest,
// not even a JBRouterTerminal — no DIRECTORY()).
function routerTerminalFor(chainId) { return getAddress('JBRouterTerminalRegistry', chainId); }

// Cash out protocol fee (2.5%), mirroring JBMultiTerminal._cashOutTokensOf. NON-ZERO cash out tax → fee on the
// full reclaim; ZERO tax → fee only on min(reclaim, feeFreeSurplus) (round-trip prevention), 0 if no fee-free
// surplus. Feeless casher → 0. All amounts are the reclaim token's own units (BigInt). Pure for testability.
export function cashOutProtocolFee(reclaim, taxRate, feeless, feeFreeSurplus) {
  reclaim = reclaim || 0n;
  if (feeless || reclaim <= 0n) return 0n;
  if (taxRate) return reclaim / 40n;
  var ffs = feeFreeSurplus || 0n;
  var feeable = reclaim < ffs ? reclaim : ffs;
  return feeable / 40n;
}

// Ambient cash-out figures (You-card cash out column, Composition unit value) show what a cash out would
// actually pay: the raw reclaim net of the 2.5% protocol fee, matching the cash-out modal's quote. Ambient
// surfaces assume a non-feeless casher (feeless status is a per-wallet nicety the modal checks exactly).
export function ambientNetCashOut(gross, taxRate, feeFreeSurplus) {
  if (gross == null) return gross;
  var value = toBigInt(gross);
  return value - cashOutProtocolFee(value, taxRate, false, feeFreeSurplus);
}

// Like ambientNetCashOut, but honest about a FAILED fee-free read: on a zero-tax project the fee
// depends on feeFreeSurplusOf, so when that read failed (null) the net is unknowable — return the
// gross flagged `beforeFees` so the UI can append the existing "before fees" qualifier instead of
// presenting gross as net. A verified 0n fee-free surplus is a real answer (no fee) and stays unflagged.
export function ambientCashOutDisplay(gross, taxRate, feeFreeSurplus) {
  if (gross == null) return { value: null, beforeFees: false };
  var value = toBigInt(gross);
  if (!taxRate && feeFreeSurplus == null) return { value: value, beforeFees: value > 0n };
  return { value: ambientNetCashOut(value, taxRate, feeFreeSurplus), beforeFees: false };
}

// Keep the submit guard on the same route/output the modal is visibly previewing. Pool-route quotes can
// legitimately replace a zero treasury quote; leaving `state.net` on the treasury value makes the button
// display a valid swap and then reject it as a zero-output cash out.
export function applyCashOutPreviewQuote(state, quote, accounting) {
  state.net = quote.net;
  state.outcome = {
    net: quote.net,
    sym: accounting.symbol,
    decimals: accounting.decimals,
    revToken: null,
    protoToken: null,
  };
}

// The hook's executable quote already includes pool fee, liquidity and impact.
// User slippage covers movement after that preview; it must not be applied to
// the optimistic raw oracle/direct quote used only for display.
export function cashOutExecutableMinimum(executableQuote, slippageBps) {
  return quotedOutputFloor(executableQuote, 10000 - (slippageBps || 0));
}

export function cashOutPoolBufferBps(rawQuote, executableQuote) {
  if (rawQuote == null || rawQuote <= 0n || executableQuote == null) return null;
  var bounded = executableQuote > rawQuote ? rawQuote : executableQuote;
  return Number(((rawQuote - bounded) * 10000n + rawQuote - 1n) / rawQuote);
}

export function cashOutDirectRouteWins(directQuote, terminalExpected, slippageBps, spendableCount, cashOutCount) {
  directQuote = directQuote == null ? 0n : toBigInt(directQuote);
  terminalExpected = terminalExpected == null ? 0n : toBigInt(terminalExpected);
  spendableCount = spendableCount == null ? 0n : toBigInt(spendableCount);
  cashOutCount = cashOutCount == null ? 0n : toBigInt(cashOutCount);
  return directQuote > 0n && cashOutCount > 0n && spendableCount >= cashOutCount
    && cashOutExecutableMinimum(directQuote, slippageBps == null ? 100 : Number(slippageBps)) > terminalExpected;
}

export function cashOutExecutionErrorMessage(message) {
  var text = String(message || 'Cash out failed.');
  if (text.indexOf('0xe2d708a9') !== -1 || text.toLowerCase().indexOf('jbbuybackhook_specifiedslippageexceeded') !== -1) {
    return 'The buyback pool moved below your protected minimum. Refresh the quote or choose a larger max slippage, then try again.';
  }
  if (text.indexOf('0x6b2bb382') !== -1 || text.toLowerCase().indexOf('jbmultiterminal_undermin') !== -1) {
    // UnderMin also fires when the hook flips a treasury-route cash out to the AMM at
    // execution: the trade is refused safely, but nothing about the user's slippage floor was
    // wrong. Naming only the floor invited people to lower it in response to a route change.
    return 'The cash out was refused because the return at execution was below your minimum — '
      + 'either the price moved, or the route switched between the treasury and the pool. '
      + 'Refresh the quote and review the route before trying again.';
  }
  return text;
}

// The cash out tax rate from a decoded currentRulesetOf result ([ruleset, metadata] array or
// { ruleset, metadata } object), falling back when the read failed or carried no metadata. Lets
// per-chain surfaces use each chain's OWN ruleset tax instead of assuming the home chain's.
export function taxRateFromRulesetResult(result, fallback) {
  var md = result == null ? null : (Array.isArray(result) ? result[1] : result.metadata);
  var v = md == null ? null : md.cashOutTaxRate;
  return v == null ? Number(fallback || 0) : Number(v);
}

// Pick the pay token after the onchain accounting-context refine resolves the real token list. Preserve the
// user's pick ONLY when they explicitly chose one (tokenTouched); otherwise default to the project's first
// accounting token (list[0]). This is the fix for the fund-loss desync where a USDC-accounting project stayed
// stuck on the native-ETH sync default (the dropdown showed USDC but the tx paid 1 ETH). Pure for testability.
export function chooseRefinedPayToken(list, currentToken, tokenTouched) {
  list = list || [];
  var keep = tokenTouched && list.filter(function (t) {
    return currentToken && t.address.toLowerCase() === currentToken.address.toLowerCase() && t.viaRouter === currentToken.viaRouter;
  })[0];
  return keep || list[0] || null;
}

function isZeroishAddress(address) {
  return !address || String(address).toLowerCase() === ZERO_ADDRESS.toLowerCase() || /^0x0+$/.test(String(address));
}

export function recognizeProjectContract(address, chainId) {
  if (isZeroishAddress(address)) return { address: address || ZERO_ADDRESS, known: true, name: null };
  var name = resolveContractName(address, chainId);
  return { address: address, known: !!name, name: name || null };
}

function sameAddr(a, b) {
  return !!(a && b && String(a).toLowerCase() === String(b).toLowerCase());
}

