      if ((hint._raw || '').toLowerCase() !== lc) return;
      if (info && info.token === lc) hint.textContent = 'JB ' + info.label + ' on ' + chainNameOf(chainId);
      else if (opts.unknownLabel) hint.textContent = opts.unknownLabel(raw, chainId);
