async function fetchRulesetQueueRows(project) {
  var deployments = projectDeployments(project);
  if (!deployments.length) return [];
  // Preferred path — fully indexed (PR #15: rulesetQueuedEvent carries basedOnId + cycleNumber): build rows with
  // NO onchain read. Auto-activates when those fields land; until then the query throws and we fall through.
  try {
    var fitems = await fetchRulesetQueuedEvents(RULESET_QUEUED_FULL_QUERY, deployments);
    // Trust the index ONLY when basedOnId + cycleNumber are actually populated — a migrated-but-not-yet-backfilled
    // schema returns the fields as null, and skipping every null-basedOnId row would silently drop ruleset rows
    // instead of falling back to allOf. Any null → fall through to the onchain path.
    var populated = fitems.length && fitems.every(function (e) { return e.basedOnId != null && e.cycleNumber != null; });
    if (populated) {
      var frows = [];
      fitems.forEach(function (e) {
        if (!(Number(e.basedOnId) > 0)) return; // genesis (basedOnId 0) shows as "created the project"
        if (Number(e.rulesetId) - Number(e.basedOnId) <= 60) return; // deploy-time stages (consecutive ids)
        frows.push({ type: 'queue_ruleset', direction: '', chainId: Number(e.chainId), txHash: e.txHash || '',
          timestamp: Number(e.rulesetId), account: e.from, from: e.from, baseAmount: '', tokenAmount: '',
          action: 'queued Ruleset #' + Number(e.cycleNumber), memo: '' });
      });
      return frows;
    }
  } catch (_) { /* basedOnId/cycleNumber not indexed yet — use the allOf fallback below */ }
  // Fallback: caller + tx from the index, keyed by chainId|rulesetId; basedOnId + cycleNumber from a cheap allOf.
  var callerByKey = {};
  try {
    var queuedItems = await fetchRulesetQueuedEvents(RULESET_QUEUED_QUERY, deployments);
    queuedItems.forEach(function (e) {
      if (e.from) callerByKey[e.chainId + '|' + String(e.rulesetId)] = { caller: e.from, txHash: e.txHash };
    });
  } catch (_) {}
  var rows = [];
  await Promise.all(deployments.map(async function (deployment) {
    var cid = deployment.chainId;
    var rs = await readAllRulesets(cid, BigInt(deployment.projectId));
    if (!rs || !rs.length) return;
    var queued = rs.filter(function (r) { return Number(r.basedOnId) !== 0 && Number(r.id) > 0; });
    if (!queued.length) return;

    queued.forEach(function (r) {
      // Hide rulesets queued as part of the deploy. The launch queues the genesis + all its stages TOGETHER in
      // one tx, so they get consecutive rulesetIds (rulesetId == queue timestamp, collision-incremented) — i.e.
      // each stage's `id` is right after its `basedOnId`. A separately, manually-queued ruleset is based on the
      // then-current ruleset but queued much later, so `id - basedOnId` is large. The genesis (basedOnId == 0)
      // is already excluded above; this drops the rest of the deploy cluster. (Verified on BAN: id-based == 1.)
      if (Number(r.id) - Number(r.basedOnId) <= 60) return;
      var info = callerByKey[cid + '|' + String(r.id)];
      // Label by cycle NUMBER (stable across chains) so the same ruleset queued on every chain groups into one
      // row — the rulesetId differs per chain (it's the local queue timestamp) and would split the rows apart.
      if (info && info.caller) {
        rows.push({
          type: 'queue_ruleset', direction: '', chainId: cid,
          txHash: info.txHash || '', timestamp: Number(r.id), account: info.caller, from: info.caller,
          baseAmount: '', tokenAmount: '',
          action: 'queued Ruleset #' + Number(r.cycleNumber), memo: '',
        });
      } else {
        rows.push({
          type: 'queue_ruleset', system: true, direction: '', chainId: cid,
          txHash: '', timestamp: Number(r.id), account: '', from: '',
          baseAmount: '', tokenAmount: '',
          action: 'Ruleset #' + Number(r.cycleNumber) + ' queued', memo: '',
        });
      }
    });
  }));
  return rows;
}

// Reconstruct bridge transactions from chain state. (Bendystraw now indexes V6, but the action-critical
// data isn't there: the merkle PROOF needed to claim isn't indexed — revnet-app fetches it from a separate
