      var group = byTier[tid].slice().sort(function (a, b) { return (BigInt(a.tokenId) < BigInt(b.tokenId)) ? -1 : (BigInt(a.tokenId) > BigInt(b.tokenId)) ? 1 : 0; });
      var gh = el('div', 'redeem-tier-head');
