        cb.addEventListener('change', function () { state.selected[o.tokenId] = cb.checked; renderItems(meta); schedulePreview(); });
        row.appendChild(cb);
        var t = el('span', 'redeem-item-id'); t.textContent = '#' + o.tokenId; row.appendChild(t);
        itemsBox.appendChild(row);
