  // Set localStorage['jb-lp-logs-rpc:84532'] = '<archive rpc url>' — keeps API-key-bearing URLs out of the build.
  var override; try { override = localStorage.getItem('jb-lp-logs-rpc:' + chainId); } catch (e) {}
